WITH youngest_client AS (
    SELECT birth_date FROM client ORDER BY birth_date ASC LIMIT 1
), young_clients AS (
    SELECT client_id FROM client WHERE birth_date = (SELECT birth_date FROM youngest_client)
), highest_avg_salary AS (
    SELECT account_id FROM account WHERE A11 = (SELECT AVG(A11) FROM account WHERE client_id IN (SELECT client_id FROM young_clients))
)
SELECT account_id FROM highest_avg_salary;

